export const GROUPS=[...new Set(PARAMETERS.map(p=>p.group))];
export const DEFAULTS=Object.fromEntries(PARAMETERS.map(p=>[p.key,p.value]));
export function sanitize(raw={}) {
 const params={...DEFAULTS};
 for(const definition of PARAMETERS){
  const defaultValue=definition.key==='initialGovernmentShare' ? raw.governmentShare??definition.value : definition.value;
  const legacySpread=definition.key==='loanSpread'&&raw.loanRate!=null ? Number(raw.loanRate)-params.initialPolicyRate : undefined;
  const supplied=Number(raw[definition.key]??legacySpread??defaultValue);
  if(!Number.isFinite(supplied))throw Error('Invalid '+definition.label);
  const bounded=Math.max(definition.min,Math.min(definition.max,supplied));
  params[definition.key]=definition.integer?Math.round(bounded):bounded;
 }
 return params;
}
