export function metricValue(row,key) {
 if(row.publicDebtBridgeDefined===0&&['publicDebtRatioChange','publicDebtDeficitContribution','publicDebtOtherFlowsContribution','publicDebtGDPContribution'].includes(key))return null;
 if(row.initialObservation&&['publicDebtStockChange','publicDebtStockFlowAdjustment'].includes(key))return null;
 if(key==='publicDeficit'&&row.publicDeficitDefined===0)return null;
 if(key==='publicDeficitGDP'&&row.publicDeficitRatioDefined===0)return null;
 if(row.initialObservation&&['importInputCostGrowth','importedCostPriceContribution'].includes(key))return null;
 if(row.privateDebtBridgeDefined===0&&['privateDebtGDPChange','debtRatioCreditContribution','debtRatioGDPContribution'].includes(key))return null;
 if(row.initialObservation&&row.foreignGovOpeningKnown===0&&key.startsWith('foreignHeldGovernment'))return null;
 if(row.initialObservation&&row.openingMacroBenchmark&&['currentAccount','nationalSaving','grossInvestment'].includes(key))return row[key];
 if(row.initialObservation&&['tfpGrowth','technologyTFPGrowth'].includes(key))return null;
 if(['labourIncomeShare','capitalIncomeShare'].includes(key)&&row.factorIncomeSharesDefined===0)return null;
 const donor=key.match(/^foreign(?:TFPIndex|TFPGrowth|BaselineGrowth|Contacts|Gain)?(USA|CHN|EUR|ROW)$/)?.[1];
 if(donor&&row['foreignDonorActive'+donor]===0)return null;
 if(['publicDefensePurchases','publicDefenseGDP'].includes(key)&&row.defenseAllocationKnown===0)return null;
 if(row.initialObservation&&row.fiscalCurrentSplitKnown===0&&['publicCurrentRevenue','publicCurrentExpenditure','publicCurrentRevenueGDP','publicCurrentExpenditureGDP','publicSaving'].includes(key))return null;
 if(['publicHealthcareGDP','publicEducationServicesGDP','publicOldAgeCashGDP','publicSocialSpendingGDP','publicCurrentRevenueGDP','publicCurrentExpenditureGDP'].includes(key)&&row.publicBudgetRatioDefined===0)return null;
 if((key==='incomeGini'&&row.incomeGiniDefined===0)||(key==='wealthGini'&&row.wealthGiniDefined===0)||(key==='netWealthGini'&&row.netWealthGiniDefined===0))return null;
 if(['publicDebtGDP','privateDebtGDP'].includes(key)&&row.debtRatioDefined===0)return null;
 return row.initialObservation&&OPENING_FLOWS.has(key)&&!(row.fiscalOpeningBenchmark&&['publicCurrentRevenue','publicCurrentExpenditure','publicCurrentRevenueGDP','publicCurrentExpenditureGDP','publicSaving'].includes(key)) ? null : row[key];
}
